# Import of required libraries
import skyramp
import os
import re
import time

from SkyrampUtils import create_application, update_application


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:8090")

def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["X-Gotify-Key"] = os.getenv("SKYRAMP_TEST_TOKEN")

    application_POST_response = create_application(
        client,
        headers,
        "partial-update-probe",
        "original description",
        7,
    )

    assert skyramp.get_response_value(application_POST_response, "name") == "partial-update-probe"
    assert skyramp.get_response_value(application_POST_response, "description") == "original description"
    assert skyramp.get_response_value(application_POST_response, "defaultPriority") == 7
    assert skyramp.get_response_value(application_POST_response, "internal") is False
    assert skyramp.get_response_value(application_POST_response, "image") == "static/defaultapp.png"
    assert int(skyramp.get_response_value(application_POST_response, "id")) > 0
    assert skyramp.get_response_value(application_POST_response, "token") is not None
    assert re.match(r"^\d{4}-\d{2}-\d{2}T", str(skyramp.get_response_value(application_POST_response, "createdAt")))

    created_application_id = skyramp.get_response_value(application_POST_response, "id")
    created_sort_key = skyramp.get_response_value(application_POST_response, "sortKey")

    application_application_PUT_response = update_application(
        client,
        headers,
        created_application_id,
        "partial-update-probe-renamed",
    )

    assert skyramp.get_response_value(application_application_PUT_response, "id") == created_application_id
    assert skyramp.get_response_value(application_application_PUT_response, "name") == "partial-update-probe-renamed"
    assert skyramp.get_response_value(application_application_PUT_response, "sortKey") == created_sort_key
    assert skyramp.get_response_value(application_application_PUT_response, "internal") is False
    assert skyramp.get_response_value(application_application_PUT_response, "image") == "static/defaultapp.png"
    assert skyramp.get_response_value(application_application_PUT_response, "description") == "original description"
    assert skyramp.get_response_value(application_application_PUT_response, "defaultPriority") == 7


if __name__ == "__main__":
    test_integration()
